CREATE SCHEMA IF NOT EXISTS qq_pocket;
REVOKE ALL ON SCHEMA qq_pocket FROM PUBLIC, anon, authenticated;
SET search_path TO qq_pocket;
CREATE TABLE IF NOT EXISTS jobs (id TEXT PRIMARY KEY, task TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, available DOUBLE PRECISION NOT NULL, lease DOUBLE PRECISION NOT NULL DEFAULT 0, token TEXT, result TEXT); CREATE INDEX IF NOT EXISTS jobs_ready ON jobs(status, available); CREATE TABLE IF NOT EXISTS demo_limits (bucket BIGINT PRIMARY KEY, count INTEGER NOT NULL);
